// The companion assembly generated by avx512-check.py keeps 28 live scalar
// results, exceeds the 24-slot cache, and stores every lane for the oracle.
#include <stdint.h>
#include <stdio.h>
extern void pressure(uint64_t out[32][2], const uint64_t in[32][2]);
int main(void) {
    uint64_t in[32][2], out[32][2], hash = 0x123456789abcdef0ULL;
    for (unsigned seed = 0; seed < 4; seed++) {
        for (unsigned n = 0; n < 32; n++) {
            in[n][0] = 0x3ff0000000000000ULL + ((uint64_t)n << 48) + seed;
            in[n][1] = 0x4000000000000000ULL + ((uint64_t)n << 48) + seed;
        }
        if (seed & 1) { in[1][0] = 0xfff0000000001234ULL; in[23][0] = 0x7ff8000000005678ULL; }
        if (seed & 2) { in[2][0] = 0x7ff0000000000000ULL; in[31][0] = 0; }
        pressure(out, in);
        for (unsigned n = 0; n < 32; n++) for (unsigned lane = 0; lane < 2; lane++)
            hash = (hash ^ out[n][lane]) * 0x100000001b3ULL;
    }
    printf("pressure %016llx\n", (unsigned long long)hash);
    return 0;
}
